    "starterCode": "public class LRUCache {\n    public LRUCache(int capacity) {\n        // TODO: Initialize\n    }\n    public int Get(int key) {\n        // TODO: Get\n        return -1;\n    }\n    public void Put(int key, int value) {\n        // TODO: Put\n    }\n}",
    "solution": "using System.Collections.Generic;\n\npublic class LRUCache {\n    private readonly int _capacity;\n    private readonly LinkedList<(int key, int val)> _list = new();\n    private readonly Dictionary<int, LinkedListNode<(int key, int val)>> _map = new();\n\n    public LRUCache(int capacity) {\n        _capacity = capacity;\n    }\n\n    public int Get(int key) {\n        if (!_map.TryGetValue(key, out var node)) return -1;\n        _list.Remove(node);\n        _list.AddFirst(node);\n        return node.Value.val;\n    }\n\n    public void Put(int key, int value) {\n        if (_map.TryGetValue(key, out var node)) {\n            _list.Remove(node);\n            node.Value = (key, value);\n            _list.AddFirst(node);\n            return;\n        }\n        if (_map.Count >= _capacity) {\n            var last = _list.Last;\n            _map.Remove(last.Value.key);\n            _list.RemoveLast();\n        }\n        var newNode = _list.AddFirst((key, value));\n        _map[key] = newNode;\n    }\n}",
    "hint": "Combine LinkedList<(int key, int val)> for ordering with Dictionary<int, LinkedListNode<(int, int)>> for O(1) lookup.",
    "approach": "Doubly linked list with dictionary node indexing.",
    "timeComplexity": "O(1) for Get and Put",
    "spaceComplexity": "O(capacity)",
